<script setup>
import RedesignTopbar from './RedesignTopbar.vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminSidebar from './AdminSidebar.vue';

const props = defineProps({ groups: Object, filters: Object, jobs: { type: Array, default: () => [] } });
const page = usePage();
const search = ref(props.filters?.search || '');
const view = ref(props.filters?.view || 'active');
const jobId = ref(props.filters?.job_id || '');
const items = computed(() => props.groups?.data || []);
const filter = () => router.get(route('redesign.study-groups'), { search: search.value || undefined, view: view.value === 'active' ? undefined : view.value, job_id: jobId.value || undefined }, { preserveState: true });
const reset = () => { search.value = ''; view.value = 'active'; jobId.value = ''; router.get(route('redesign.study-groups')); };
const setView = (value) => { view.value = value; filter(); };
</script>

<template>
    <Head title="Study groups" />
    <div class="groups-app"><AdminSidebar /><main>
        <RedesignTopbar breadcrumb="Program & kelas" />
        <div class="content">
            <div class="heading"><div><h1>Study groups</h1><p>Kelola kapasitas, level minimum, job, dan keanggotaan.</p></div><Link v-if="page.props.auth?.user?.role === 'super_admin' || page.props.auth?.user?.role === 'admin'" class="primary" :href="route('redesign.study-groups.create', jobId ? {job_id:jobId} : {})">+ Buat study group</Link></div>
            <div v-if="page.props.flash?.message === 'NEW_PARTY_ESTABLISHED'" class="notice" role="status">Study group berhasil dibuat.</div>
            <div v-if="page.props.flash?.message === 'DATA_UPDATED_SUCCESSFULLY'" class="notice" role="status">Study group berhasil diperbarui.</div>
            <div class="tabs" role="group" aria-label="Tampilan study group"><button :class="{active:view==='active'}" @click="setView('active')">Semua</button><button :class="{active:view==='pending'}" @click="setView('pending')">Permintaan gabung</button><button :class="{active:view==='trash'}" @click="setView('trash')">Arsip</button></div>
            <form class="filters" @submit.prevent="filter"><input v-model="search" aria-label="Cari kelas" placeholder="Cari nama atau kata kunci..." /><select v-model="jobId" aria-label="Filter job"><option value="">Semua job</option><option v-for="job in jobs" :key="job.id" :value="job.id">{{ job.name }}</option></select><button type="submit">Filter</button><button type="button" @click="reset">Reset</button></form>
            <div class="group-grid"><article v-for="(group,index) in items" :key="group.uuid" class="group-card"><div class="card-top"><span class="number">{{ String(((groups.current_page || 1)-1)*(groups.per_page || 10)+index+1).padStart(2,'0') }}</span><span class="badge" :class="{ archived:view==='trash', pending:view==='pending' }">{{ view === 'trash' ? 'Arsip' : view === 'pending' ? `${group.pending_requests_count || 0} menunggu` : 'Aktif' }}</span></div><h2>{{ group.name }}</h2><p>{{ group.users_count || 0 }} peserta · {{ group.staff_count || 0 }} mentor · {{ group.quests_count || 0 }} quest</p><small>{{ group.job?.name || 'Tanpa job' }} · kapasitas {{ group.max_members || 0 }} · level {{ group.min_level || 1 }}+</small><div class="card-actions"><Link v-if="view === 'pending'" :href="route('redesign.study-groups.membership', group.uuid)">Lihat permintaan →</Link><Link v-else-if="view !== 'trash'" :href="route('redesign.study-groups.show', group.uuid)">Buka detail →</Link><Link v-if="view !== 'trash' && (page.props.auth?.user?.role === 'super_admin' || page.props.auth?.user?.role === 'admin')" :href="route('redesign.study-groups.edit', group.uuid)">Edit</Link><span v-if="view === 'trash'">Kelas diarsipkan</span></div></article><div v-if="!items.length" class="empty">{{ view === 'trash' ? 'Belum ada kelas di arsip.' : view === 'pending' ? 'Belum ada permintaan gabung yang menunggu.' : 'Tidak ada study group yang cocok.' }}</div></div>
            <nav v-if="groups?.links?.length > 3" class="pagination" aria-label="Halaman kelas"><Link v-for="(link,index) in groups.links" :key="index" :href="link.url || '#'" :class="{ active:link.active, disabled:!link.url }" v-html="link.label" /></nav>
        </div>
    </main></div>
</template>

<style scoped>
.groups-app{display:flex;min-height:100vh;background:#f5f7f8;color:#19333d;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.groups-app main{flex:1;min-width:0}.topbar{height:64px;background:#fff;border-bottom:1px solid #dce6e8;padding:0 28px;display:flex;align-items:center;justify-content:space-between;color:#70858c;font-size:11px}.topbar strong,.topbar small{display:block}.topbar strong{color:#19333d;font-size:12px}.topbar small{font-size:10px}.content{max-width:1320px;margin:auto;padding:30px 26px 60px}.heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:30px}.heading h1{font-size:30px;font-weight:750;letter-spacing:-.025em;margin:0}.heading p{font-size:13px;color:#70858c;margin:8px 0 0}.primary{background:#007f78;color:#fff;border:0;border-radius:8px;padding:13px 20px;font-weight:700;cursor:pointer}.tabs{display:flex;gap:10px;margin-bottom:24px;flex-wrap:wrap}.tabs button,.filters button{border:1px solid #dce6e8;border-radius:8px;background:#fff;color:#6b8187;padding:11px 18px;font-size:12px;cursor:pointer}.tabs button.active{background:#e5f5f1;color:#007f78;border-color:#e5f5f1;font-weight:700}.filters{display:grid;grid-template-columns:minmax(0,1fr) 190px auto auto;gap:12px;margin-bottom:28px}.filters input,.filters select{border:1px solid #dce6e8;border-radius:8px;background:#fff;padding:12px 16px;min-width:0}.filters button{color:#007f78;font-weight:700}.group-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.group-card{background:#fff;border:1px solid #dce6e8;border-radius:12px;padding:22px;min-width:0}.card-top{display:flex;justify-content:space-between;gap:12px;align-items:start}.number{display:grid;place-items:center;width:54px;height:54px;border-radius:12px;background:#e5f5f1;color:#007f78;font-size:21px;font-weight:750}.badge{background:#e5f5f1;color:#007f78;border-radius:6px;padding:7px 12px;font-size:11px;font-weight:700}.badge.archived,.badge.pending{background:#fff2d8;color:#9d651